SELECT toJSONString(tuple(count(),sum(rows))) AS payload FROM (SELECT part_name,max(rows) AS rows FROM clusterAllReplicas(default,merge('system','^part_log')) PREWHERE event_date BETWEEN '2026-08-08' AND '2026-08-09' AND event_time>=toDateTime('2026-08-08 06:55:56','UTC') AND event_time<toDateTime('2026-08-09 19:40:58','UTC') WHERE table_uuid=toUUID('51ef6752-cdc7-4d90-bd20-b295dfbd561e') AND error=0 AND event_type IN ('NewPart','MergeParts') GROUP BY part_name LIMIT 1000000) WHERE part_name NOT IN (SELECT input_part FROM (SELECT arrayJoin(merged_from) AS input_part FROM clusterAllReplicas(default,merge('system','^part_log')) PREWHERE event_date BETWEEN '2026-08-08' AND '2026-08-09' AND event_time>=toDateTime('2026-08-08 06:55:56','UTC') AND event_time<toDateTime('2026-08-09 19:40:58','UTC') WHERE table_uuid=toUUID('51ef6752-cdc7-4d90-bd20-b295dfbd561e') AND error=0 AND event_type='MergeParts') GROUP BY input_part LIMIT 1000000) LIMIT 1 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=5000000,max_memory_usage=1500000000,skip_unavailable_shards=1;
